                         </p>
                     </div>
                     {isLoggedIn ? (
                         <button
                             type="button"
                             className="button button--outline"
                             onClick={handleLogout}
                         >
                             로그아웃
                         </button>
                     ) : (
                         <Link href="/account/login" className="button button--dark">
                             로그인
                         </Link>
                     )}
                 </section>

                 {/* 통계 카드 */}
                 <div className="account-stats">
                     <button
                         type="button"
                         className="account-stat-card"
                         onClick={() => setActiveTab("bookings")}
