import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const v5Root = path.resolve(__dirname, "..");
const outDir = path.resolve(v5Root, "out");

function copyRecursive(src, dest) {
    if (!fs.existsSync(src)) return;
    const stats = fs.statSync(src);
    if (stats.isDirectory()) {
        if (!fs.existsSync(dest)) {
            fs.mkdirSync(dest, { recursive: true });
        }
        for (const child of fs.readdirSync(src)) {
            copyRecursive(path.join(src, child), path.join(dest, child));
        }
    } else {
        fs.copyFileSync(src, dest);
    }
}

if (fs.existsSync(outDir)) {
    const staticDir = path.join(outDir, "_next", "static");
    if (["development", "webpack"].some((name) => fs.existsSync(path.join(staticDir, name)))) {
        throw new Error("Development assets found in the export. Stop the dev server, remove v5/.next and v5/out, then run the production build again.");
    }
    console.log("Syncing out/ to v5 root for direct static hosting...");
    copyRecursive(outDir, v5Root);
    console.log("Sync completed successfully!");
}

parts.text:
The script copies without pruning. Two-part fix:

1. Delete the stale chunks right now (remove files; commit deletions).
2. Make sync-out.js prune stale files under `v5/_next` (destination `_next` tree exists only from out/ mirror → safe to delete-and-mirror entirely) so this never recurs. Deleting `_next` wholesale then copying is safe: `v5/_next` is fully build-derived (not repo-authored). Implement: if dest `_next` exists → rmSync; then copyRecursive.

Also note untracked `v5/_next/static/2TCfKZPNWRHH4CVlDVvgN/` etc. — buildId dirs accumulate too. rmSync on `_next` cleans all.

Keep the change minimal: import fs already; add function ensureMirror(dest) that removes dest dir if exists. Implementation:

```js
function mirrorDirectory(src, dest) {
    if (fs.existsSync(dest)) {
        fs.rmSync(dest, { recursive: true, force: true });
    }
    copyRecursive(src, dest);
}
```

Use for `_next` only? If we mirror ALL of out→v5 root we'd delete site pages too (they exist only in out; rm whole root = nuke). So: delete `dest/_next` before copy, rest top-over as-is. Copy path = v5Root; so pre-step: `const nextDir = path.join(v5Root, "_next"); if exists rmSync(nextDir)`.

Then rerun build? No — just run postbuild directly: node scripts/sync-out.js (out/ still fresh from previous build). That mirrors clean _next. Confirm stale gone & new chunks present. Then commit all + push with message per guideline: "fix: v5 사이트 문구에서 AI티 표현 제거 및 빌드 산출물 정리" — commit message guideline: [접두사]: [한국어 설명]. Also AGENTS says always push origin main after commit.

Also handle summary/reflection record — compromising: keep commit message descriptive; repo docs update not requested. AGENTS guideline says write reflections... but no established docs/summary pattern known; writing docs without request conflicts "never proactively create documentation". Better: put key criteria into AGENTS.md? Also unrequested. Skip file writing; mention the cleanup rule in commit body instead. Also add to commit message? Keep simple.

