const names: Record<string, string> = {
    arrow: "arrow_forward",
    back: "arrow_back",
    diagonal: "arrow_outward",
    up: "arrow_upward",
    search: "search",
    menu: "menu",
    close: "close",
    calendar: "calendar_month",
    pin: "location_on",
    ticket: "confirmation_number",
