import fs from "fs";
import path from "path";

const root = "C:\\Users\\hi\\renewsejongpac-3\\v5\\public\\assets\\icons";
const NAMES = [
    "arrow_forward", "arrow_back", "arrow_outward", "arrow_upward", "search", "menu", "close",
    "calendar_month", "location_on", "confirmation_number", "person", "favorite",
    "favorite-fill", "chevron_right", "schedule", "add", "check", "accessible",
    "directions_car", "apartment", "local_cafe", "mail", "download", "play_arrow", "pause",
    "refresh", "home", "undo", "content_copy", "open_in_new",
];

const prev = fs.readFileSync(path.join(root, "material-symbols-rounded.svg"), "utf8");
const before = (prev.match(/<symbol /g) || []).length;
const symbols = NAMES.map((name) => {
    const source = fs.readFileSync(path.join(root, "rounded", name + ".svg"), "utf8");
    const viewBox = (source.match(/viewBox="([^"]+)"/) || [])[1];
    if (!viewBox) throw new Error("missing viewBox: " + name);
