});
const sprite = `<svg xmlns="http://www.w3.org/2000/svg">` + symbols.join("") + `</svg>\n`;
fs.writeFileSync(path.join(root, "material-symbols-rounded.svg"), sprite);
console.log("sprite symbols: " + before + " -> " + symbols.length);

