input.content:
/* ==========================================================================
   [커스텀 우클릭 컨텍스트 메뉴 / Custom Right-click Context Menu]
   네이티브 우클릭을 대체해 둥근 모던 패널로 페이지·링크 작업을 제공합니다.
   Replaces the native context menu with a rounded modern panel offering page and link actions.
   ========================================================================== */

.shell {
    position: fixed;
    z-index: 1200;
    min-width: 232px;
    max-width: 340px;
    padding: 8px;
    background: var(--paper, #fff);
    border: 1px solid var(--line, #d9d9d4);
    border-radius: 1.5rem;
    box-shadow: 0 0.5rem 1.5rem rgb(17 20 38 / 12%);
    color: var(--ink, #000);
    font-family: var(--font, inherit);
    transform-origin: top left;
    animation: shell-in 170ms cubic-bezier(0.33, 1, 0.68, 1) both;
}

@keyframes shell-in {
    from {
        opacity: 0;
        transform: scale(0.92) translateY(4px);
    }
    to {
        opacity: 1;
        transform: translate(0) scale(1);
    }
}

.list {
    display: grid;
    gap: 2px;
}

.item {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
    min-height: 48px;
    padding: 0 12px;
    border: 0;
    border-radius: 1.25rem;
    background: transparent;
    font: inherit;
    font-size: var(--text-sm, 1rem);
    line-height: 1.5;
    font-weight: var(--weight-action, 600);
    color: inherit;
    text-align: left;
    cursor: pointer;
    transition: background-color 120ms ease, color 120ms ease;
}

.item:hover {
    background: var(--soft, #f7f7f5);
    color: var(--ink, #000);
}

.item:active {
    background: var(--line, #d9d9d4);
    color: var(--ink, #000);
}

.item:disabled {
    color: var(--action-disabled-text, #626262);
    cursor: default;
    background: transparent;
}

.item > .material-icon {
    width: 20px;
    height: 20px;
    flex: none;
    color: var(--ink-secondary, #626262);
}

.item:active > .material-icon {
    color: var(--ink, #000);
}

.divider {
    height: 1px;
    margin: 6px 10px;
    background: var(--line, #d9d9d4);
}

.location {
    padding: 8px 14px 6px;
    font-size: var(--text-sm, 1rem);
    font-weight: var(--weight-label, 500);
    line-height: 1.5;
    color: var(--muted, #626262);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
    .shell {
        animation: none;
    }
}

// ==========================================================================
// [커스텀 우클릭 컨텍스트 메뉴 / Custom Right-click Context Menu]
// 우클릭 시 토큰 기반 둥근 메뉴를 띄우고 페이지·링크 작업을 실행한다.
// Opens a token-based rounded menu on right click and runs page or link actions.
// ==========================================================================
"use client";

import React, { useEffect, useLayoutEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import Icon from "./Icon";
import { showToast } from "./Toast";
import styles from "./ContextMenu.module.css";

interface MenuState {
    x: number;
    y: number;
    href: string | null;
    canGoBack: boolean;
}

const MARGIN = 12;

export default function ContextMenu() {
    const [menu, setMenu] = useState<MenuState | null>(null);
    const shellRef = useRef<HTMLDivElement | null>(null);
    const previousFocusRef = useRef<HTMLElement | null>(null);

    useEffect(() => {
        const onContextMenu = (event: MouseEvent) => {
            const target = event.target as HTMLElement | null;
            if (target?.closest('input, textarea, select, [contenteditable="true"], [contenteditable=""]')) {
                return;
            }
            event.preventDefault();
            const anchor = target?.closest("a[href]") as HTMLAnchorElement | null;
            previousFocusRef.current = document.activeElement as HTMLElement | null;
            setMenu({
                x: event.clientX,
                y: event.clientY,
                href: anchor?.href ?? null,
                canGoBack: window.history.length > 1,
            });
        };
        document.addEventListener("contextmenu", onContextMenu);
        return () => document.removeEventListener("contextmenu", onContextMenu);
    }, []);

    useEffect(() => {
        if (!menu) return;
        const close = (event: Event) => {
            event;
            setMenu(null);
        };
        const onKeyDown = (event: KeyboardEvent) => {
            const shell = shellRef.current;
            if (!shell) return;
            const items = Array.from(shell.querySelectorAll<HTMLButtonElement>(".item:not(:disabled)"));
            const current = document.activeElement as HTMLElement | null;
            const index = items.indexOf(current as HTMLButtonElement);
            if (event.key === "Escape" || event.key === "Tab") {
                event.preventDefault();
                previousFocusRef.current?.focus?.({ preventScroll: true });
                setMenu(null);
                return;
            }
            if (event.key === "ArrowDown" || (event.key === "Tab" && false)) {
                event.preventDefault();
                items[(index + 1) % items.length]?.focus();
            } else if (event.key === "ArrowUp") {
                event.preventDefault();
                items[(index - 1 + items.length) % items.length]?.focus();
            } else if (event.key === "End") {
                event.preventDefault();
                items[items.length - 1]?.focus();
            } else if (event.key === "Home") {
                event.preventDefault();
                items[0]?.focus();
            }
        };
        document.addEventListener("keydown", onKeyDown);
        document.addEventListener("pointerdown", onDocumentPointerDown, true);
        window.addEventListener("blur", close);
        window.addEventListener("resize", close);
        window.addEventListener("scroll", close, true);
        return () => {
            document.removeEventListener("keydown", onKeyDown);
            document.removeEventListener("pointerdown", onDocumentPointerDown, true);
            window.removeEventListener("blur", close);
            window.removeEventListener("resize", close);
            window.removeEventListener("scroll", close, true);
        };
    }, [menu != null]);

    useLayoutEffect(() => {
        const shell = shellRef.current;
        if (!menu || !shell) return;
        const rect = shell.getBoundingClientRect();
        const x = Math.max(MARGIN, Math.min(menu.x, window.innerWidth - rect.width - MARGIN));
        const y = Math.max(MARGIN, Math.min(menu.y, window.innerHeight - rect.height - MARGIN));
        shell.style.left = `${x}px`;
        shell.style.top = `${y}px`;
        shell.querySelector<HTMLButtonElement>("button:not(:disabled)")?.focus({ preventScroll: true });
    }, [menu]);

    useEffect(() => {
        return () => {
            setMenu(null);
        };
    }, []);

    const close = (restoreFocus?: boolean) => {
        if (restoreFocus) previousFocusRef.current?.focus?.({ preventScroll: true });
        setMenu(null);
    };

    const copy = async (text: string) => {
        try {
            await navigator.clipboard.writeText(text);
        } catch {
            const scratch = document.createElement("textarea");
            scratch.value = text;
            scratch.setAttribute("readonly", "");
            scratch.style.position = "fixed";
            scratch.style.opacity = "0";
            document.body.appendChild(scratch);
            scratch.select();
            document.execCommand("copy");
            scratch.remove();
        }
        showToast("주소를 복사했어요.");
        close();
    };

    const actions = menu
        ? [
              menu.href
                  ? {
                        icon: "open_in_new",
                        label: "새 창에서 열기",
                        run: () => window.open(menu.href as string, "_blank", "noopener"),
                    }
                  : null,
              menu.href
                  ? { icon: "content_copy", label: "링크 주소 복사", run: () => copy(menu.href as string) }
                  : { icon: "content_copy", label: "페이지 주소 복사", run: () => copy(window.location.href) },
          ].filter((item): item is { icon: string; label: string; run: () => void } => item !== null)
        : [];

    if (!menu) return null;

    return createPortal(
        <div
            className={styles.shell}
            ref={shellRef}
            role="menu"
            aria-label="페이지 바로가기 메뉴"
            style={{ left: menu.x, top: menu.y }}
        >
            <div className={styles.list}>
                <button type="button" role="menuitem" className={styles.item} onClick={() => { location.reload(); }}>
                    <Icon name="refresh" size={20} />
                    새로 고침
                </button>
                {actions.map((action) => (
                    <button
                        key={action.label}
                        type="button"
                        role="menuitem"
                        className={styles.item}
                        onClick={() => {
                            action.run();
                            close(false);
                        }}
                    >
                        <Icon name={action.icon} size={20} />
                        {action.label}
                    </button>
                ))}
                <button
                    type="button"
                    role="menuitem"
                    className={styles.item}
                    disabled={!menu.canGoBack}
                    onClick={() => { history.back(); }}
                >
                    <Icon name="undo" size={20} />
                    이전 페이지로
                </button>
                <button
                    type="button"
                    role="menuitem"
                    className={styles.item}
                    onClick={() => { location.href = "/v5/"; }}
                >
                    <Icon name="home" size={20} />
                    홈으로
                </button>
            </div>
            {menu.href && (
                <>
                    <div className={styles.divider} aria-hidden="true" />
                    <span className={styles.location}>{new URL(menu.href).host}{new URL(menu.href).pathname}</span>
                </>
            )}
        </div>,
        document.body
    );
}

function onDocumentPointerDown(event: PointerEvent) {
    const target = event.target as HTMLElement | null;
    if (target?.closest('[role="menu"]')) return;
    const menus = document.querySelectorAll('[role="menu"]');
    if (menus.length === 0) return;
    (document.activeElement as HTMLElement | null)?.blur?.();
    menus.forEach((el) => {
        el.dispatchEvent(new CustomEvent("sejong-menu-dismiss"));
    });
    // Listen once per shell to unmount via React state below in ContextMenu.
}

// ==========================================================================
// [커스텀 우클릭 컨텍스트 메뉴 / Custom Right-click Context Menu]
// 우클릭 시 토큰 기반 둥근 메뉴를 띄우고 페이지·링크 작업을 실행한다.
// Opens a token-based rounded menu on right click and runs page or link actions.
// ==========================================================================
"use client";

import React, { useEffect, useLayoutEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { useRouter } from "next/navigation";
import Icon from "./Icon";
import { showToast } from "./Toast";
import ContextMenuStyles from "./ContextMenu.module.css";

interface MenuState {
    x: number;
    y: number;
    href: string | null;
    canGoBack: boolean;
}

interface MenuAction {
    icon: string;
    label: string;
    run: () => void;
    closeAfter: boolean;
}

const MARGIN = 12;
const EDITABLE_SELECTOR = 'input, textarea, select, [contenteditable="true"], [contenteditable=""]';

export default function ContextMenu() {
    const router = useRouter();
    const [menu, setMenu] = useState<MenuState | null>(null);
    const shellRef = useRef<HTMLDivElement | null>(null);
    const previousFocusRef = useRef<HTMLElement | null>(null);
    const isOpen = menu !== null;

    useEffect(() => {
        const onContextMenu = (event: MouseEvent) => {
            const target = event.target as HTMLElement | null;
            // 폼 편집 중에는 네이티브 메뉴(복사·붙여넣기)를 남긴다.
            // Keep the native menu while editing form fields (copy, paste, etc.).
            if (target?.closest(EDITABLE_SELECTOR)) return;
            event.preventDefault();
            const anchor = target?.closest("a[href]") as HTMLAnchorElement | null;
            previousFocusRef.current = document.activeElement as HTMLElement | null;
            setMenu({
                x: event.clientX,
                y: event.clientY,
                href: anchor?.href ?? null,
                canGoBack: window.history.length > 1,
            });
        };
        document.addEventListener("contextmenu", onContextMenu);
        return () => document.removeEventListener("contextmenu", onContextMenu);
    }, []);

    useEffect(() => {
        if (!isOpen) return;
        const dismiss = () => setMenu(null);
        const onKeyDown = (event: KeyboardEvent) => {
            const shell = shellRef.current;
            if (!shell) return;
            const items = Array.from(shell.querySelectorAll<HTMLButtonElement>("button:not([disabled])"));
            const currentIndex = items.indexOf(document.activeElement as HTMLButtonElement);
            if (event.key === "Escape" || event.key === "Tab") {
                event.preventDefault();
                previousFocusRef.current?.focus({ preventScroll: true });
                setMenu(null);
                return;
            }
            if (event.key === "ArrowDown") {
                event.preventDefault();
                items[(currentIndex + 1) % items.length]?.focus();
            } else if (event.key === "ArrowUp") {
                event.preventDefault();
                items[(currentIndex - 1 + items.length) % items.length]?.focus();
            } else if (event.key === "Home") {
                event.preventDefault();
                items[0]?.focus();
            } else if (event.key === "End") {
                event.preventDefault();
                items[items.length - 1]?.focus();
            }
        };
        const onPointerDown = (event: PointerEvent) => {
            const target = event.target as HTMLElement | null;
            if (target?.closest('[role="menu"]')) return;
            dismiss();
        };
        document.addEventListener("keydown", onKeyDown);
        document.addEventListener("pointerdown", onPointerDown, true);
        window.addEventListener("blur", dismiss);
        window.addEventListener("resize", dismiss);
        window.addEventListener("scroll", dismiss, true);
        return () => {
            document.removeEventListener("keydown", onKeyDown);
            document.removeEventListener("pointerdown", onPointerDown, true);
            window.removeEventListener("blur", dismiss);
            window.removeEventListener("resize", dismiss);
            window.removeEventListener("scroll", dismiss, true);
        };
    }, [isOpen]);

    useLayoutEffect(() => {
        const shell = shellRef.current;
        if (!menu || !shell) return;
        const rect = shell.getBoundingClientRect();
        const x = Math.max(MARGIN, Math.min(menu.x, window.innerWidth - rect.width - MARGIN));
        const y = Math.max(MARGIN, Math.min(menu.y, window.innerHeight - rect.height - MARGIN));
        shell.style.left = `${x}px`;
        shell.style.top = `${y}px`;
        shell.querySelector<HTMLButtonElement>("button:not([disabled])")?.focus({ preventScroll: true });
    }, [menu]);

    const close = (restoreFocus: boolean = false) => {
        if (restoreFocus) previousFocusRef.current?.focus({ preventScroll: true });
        setMenu(null);
    };

    const copyAddress = async (text: string) => {
        try {
            await navigator.clipboard.writeText(text);
        } catch {
            const scratch = document.createElement("textarea");
            scratch.value = text;
            scratch.setAttribute("readonly", "");
            scratch.style.position = "fixed";
            scratch.style.opacity = "0";
            scratch.style.pointerEvents = "none";
            document.body.appendChild(scratch);
            scratch.select();
            document.execCommand("copy");
            scratch.remove();
        }
        showToast("주소를 복사했어요.");
        close(true);
    };

    if (!menu) return null;

    const linkLocation = menu.href ? new URL(menu.href) : null;
    const actions: MenuAction[] = [];
    if (linkLocation) {
        actions.push({
            icon: "open_in_new",
            label: "새 창에서 열기",
            run: () => window.open(linkLocation.href, "_blank", "noopener"),
            closeAfter: true,
        });
        actions.push({
            icon: "content_copy",
            label: "링크 주소 복사",
            run: () => { void copyAddress(linkLocation.href); },
            closeAfter: false,
        });
    } else {
        actions.push({
            icon: "content_copy",
            label: "페이지 주소 복사",
            run: () => { void copyAddress(window.location.href); },
            closeAfter: false,
        });
    }

    return createPortal(
        <div
            ref={shellRef}
            className={ContextMenuStyles.shell}
            role="menu"
            aria-label="페이지 바로가기 메뉴"
            style={{ left: menu.x, top: menu.y }}
        >
            <div className={ContextMenuStyles.list}>
                <button
                    type="button"
                    role="menuitem"
                    className={ContextMenuStyles.item}
                    onClick={() => location.reload()}
                >
                    <Icon name="refresh" size={20} />
                    새로 고침
                </button>
                {actions.map((action) => (
                    <button
                        key={action.label}
                        type="button"
                        role="menuitem"
                        className={ContextMenuStyles.item}
                        onClick={() => {
                            action.run();
                            if (action.closeAfter) close(true);
                        }}
                    >
                        <Icon name={action.icon} size={20} />
                        {action.label}
                    </button>
                ))}
                <button
                    type="button"
                    role="menuitem"
                    className={ContextMenuStyles.item}
                    disabled={!menu.canGoBack}
                    onClick={() => history.back()}
                >
                    <Icon name="undo" size={20} />
                    이전 페이지로
                </button>
                <button
                    type="button"
                    role="menuitem"
                    className={ContextMenuStyles.item}
                    onClick={() => router.push("/")}
                >
                    <Icon name="home" size={20} />
                    홈으로
                </button>
            </div>
            {linkLocation && (
                <>
                    <div className={ContextMenuStyles.divider} aria-hidden="true" />
                    <span className={ContextMenuStyles.location}>
                        {linkLocation.host}
                        {linkLocation.pathname}
                    </span>
                </>
            )}
        </div>,
        document.body
    );
}

