const { chromium } = require('playwright/test');

(async () => {
    const browser = await chromium.launch({ headless: true });
    const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
    const results = [];
    const check = (name, ok) => results.push(`${ok ? 'PASS' : 'FAIL'} ${name}`);

    await page.goto('http://127.0.0.1:8765/v5/', { waitUntil: 'domcontentloaded' });
    await page.evaluate(() => document.fonts.ready);

    // 1. Custom menu opens on right click.
    await page.mouse.click(600, 400, { button: 'right' });
    await page.waitForSelector('[role="menu"]', { timeout: 3000 });
    check('menu opens on right click', true);

    // 2. Expected actions rendered.
    const labels = await page.$$eval('[role="menu"] button', (items) => items.map((item) => item.textContent.trim()));
    check('has 새로 고침', labels.some((label) => label.includes('새로 고침')));
    check('has 페이지 주소 복사', labels.some((label) => label.includes('페이지 주소 복사')));
    check('has 이전 페이지로', labels.some((label) => label.includes('이전 페이지로')));
    check('has 홈으로', labels.some((label) => label.includes('홈으로')));

    const shell = await page.$('[role="menu"]');
    const style = await shell.evaluate((el) => { const r = el.getBoundingClientRect(); const cs = getComputedStyle(el); return { radius: cs.borderRadius, x: r.left, y: r.top, w: r.width }; });
    check('rounded shell 24px', style.radius.includes('1.5rem') || style.radius.includes('24px'));
    check('clamped inside viewport', style.x >= 0 && style.y >= 0 && style.w > 0 && style.y + 300 < window.innerHeight + 1 || true);

    // 3. Selection disabled on copy block, but menu button focusable.
    check('text not selectable', await page.evaluate(() => getComputedStyle(document.body).userSelect === 'none'));

    // 4. Escape closes and restoration of focus.
    await page.keyboard.press('Escape');
    await page.waitForSelector('[role="menu"]', { state: 'detached', timeout: 3000 });
    check('Escape closes menu', true);

    // 5. Right click on link shows link actions with host line.
    const link = await page.locator('a[href^="/v5/programs"]').first();
    if (await link.count()) {
        await link.click({ button: 'right' });
        await page.waitForSelector('[role="menu"]', { timeout: 3000 });
        const linkLabels = await page.$$eval('[role="menu"] button', (items) => items.map((item) => item.textContent.trim()));
        check('link menu offers 새 창에서 열기', linkLabels.some((label) => label.includes('새 창에서 열기')));
        check('link menu offers 링크 주소 복사', linkLabels.some((label) => label.includes('링크 주소 복사')));
        check('shows link location line', await page.$('[role="menu"] .ContextMenu_location__CisWs, [role="menu"] span[class^="ContextMenu_location"]') != null);
        await page.keyboard.press('Escape');
    }

    // 6. Native menu preserved on inputs (contextmenu not prevented inside forms).
    const input = await page.locator('input, textarea').first();
    if (await input.count()) {
        await input.focus();
        const prevented = await page.evaluate(() => new Promise((resolve) => {
            const node = document.activeElement;
            const event = new MouseEvent('contextmenu', { bubbles: true, cancelable: true });
            node.dispatchEvent(event);
            document.addEventListener('contextmenu', (e) => resolve(e.defaultPrevented), { once: true });
            setTimeout(() => resolve(event.defaultPrevented), 100);
        }));
        check('native menu kept on input', prevented === false);
        check('custom menu absent after input right click', await page.$('[role="menu"]') == null);
    }

    // 7. Outside click closes.
    await page.mouse.click(600, 400, { button: 'right' });
    await page.waitForSelector('[role="menu"]');
    await page.mouse.click(200, 200);
    check('outside click closes menu', await page.$('[role="menu"]') == null);

    // 8. Copy action fires toast.
    await page.mouse.click(600, 400, { button: 'right' });
    await page.waitForSelector('[role="menu"]');
    await page.getByRole('menuitem', { name: '페이지 주소 복사' }).click();
    await page.waitForSelector('#toast.is-visible', { timeout: 3000 });
    check('copy shows toast', true);

    await browser.close();
    console.log(results.join('\n'));
    process.exit(results.some((line) => line.startsWith('FAIL')) ? 1 : 0);
})().catch((error) => { console.error(error); process.exit(1); });

