const { chromium } = require('playwright/test');

(async () => {
    const browser = await chromium.launch({ headless: true });
    const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
    const results = [];
    const check = (name, ok) => { results.push(`${ok ? 'PASS' : 'FAIL'} ${name}`); };

    await page.goto('http://127.0.0.1:8765/v5/', { waitUntil: 'domcontentloaded' });
    await page.evaluate(() => document.fonts.ready);

    await page.mouse.click(600, 400, { button: 'right' });
    await page.waitForSelector('[role="menu"]', { timeout: 3000 });
    check('menu opens on right click', true);

    const labels = await page.$$eval('[role="menu"] button', (items) => items.map((item) => item.textContent.trim()));
    const en = await page.$$eval('[role="menu"] button', (items) => items.map((item) => item.textContent.trim()));
    check('has refresh item', en.length === 4);
    check('count exact', en.length === 4);

    const names = await page.$$eval('[role="menu"] [role="menuitem"]', (items) => items.map((item) => ({
        tag: item.tagName,
        roleAttr: item.getAttribute('role'),
        text: item.textContent.trim(),
        accessible: item.ariaLabel || item.getAttribute('aria-label') || item.textContent.trim(),
    })));
    console.log(JSON.stringify(names, null, 2));

    const menuContent = await page.$eval('[role="menu"]', (el) => el.textContent.trim());
    console.log('MENU TEXT:', JSON.stringify(menuContent));
    check('menu text contains copy action', /주소 복사/.test(menuContent));

    try {
        const item = page.locator('[role="menuitem"]').nth(1);
        await item.click();
        await page.waitForSelector('#toast.is-visible', { timeout: 3000 });
        check('copy shows toast', true);
    } catch (error) {
        check('copy shows toast: ' + error.message.split('\n')[0], false);
    }

    await browser.close();
    console.log(results.join('\n'));
    process.exit(results.some((line) => line.startsWith('FAIL')) ? 1 : 0);
})().catch((error) => { console.error(error); process.exit(1); });

const { chromium } = require('playwright/test');

(async () => {
    const browser = await chromium.launch({ headless: true });
    const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
    const results = [];
    const check = (name, ok) => { results.push(`${ok ? 'PASS' : 'FAIL'} ${name}`); };

    await page.goto('http://127.0.0.1:8765/v5/', { waitUntil: 'domcontentloaded' });
    await page.evaluate(() => document.fonts.ready);

    // Copy link address -> toast.
    await page.mouse.click(600, 400, { button: 'right' });
    await page.waitForSelector('[role="menu"]', { timeout: 3000 });
    await page.locator('[role="menuitem"]', { hasText: '복사' }).click();
    await page.waitForSelector('#toast.is-visible', { timeout: 3000 });
    check('copy shows toast', true);
    await page.waitForSelector('[role="menu"]', { state: 'detached' });
    check('closes after copy', true);
    await page.waitForTimeout(3300);

    // Escape closes.
    await page.mouse.click(300, 300, { button: 'right' });
    await page.waitForSelector('[role="menu"]');
    await page.keyboard.press('Escape');
    await page.waitForSelector('[role="menu"]', { state: 'detached' });
    check('Escape closes menu', true);

    // Outside click closes.
    await page.mouse.click(300, 300, { button: 'right' });
    await page.waitForSelector('[role="menu"]');
    await page.mouse.click(100, 800);
    await page.waitForSelector('[role="menu"]', { state: 'detached' });
    check('outside click closes menu', true);

    // Keyboard navigation: arrows move focus inside menu.
    await page.mouse.click(300, 300, { button: 'right' });
    await page.waitForSelector('[role="menu"]');
    const first = await page.evaluate(() => document.activeElement.textContent.trim().startsWith('새로'));
    check('focus to first item on open', first);
    await page.keyboard.press('ArrowDown');
    const second = await page.evaluate(() => document.activeElement.closest('[role="menu"]') !== null);
    check('ArrowDown keeps focus in menu', second);
    await page.keyboard.press('Escape');
    await page.waitForSelector('[role="menu"]', { state: 'detached' });
    check('Escape closes after arrows', true);

    // Native context menu preserved on form field.
    const inputCount = await page.locator('input:visible').count();
    if (inputCount > 0) {
        await page.locator('input:visible').first().focus();
        const prevented = await page.evaluate(() => new Promise((resolve) => {
            const node = document.activeElement;
            const handler = (e) => { resolve(e.defaultPrevented); };
            document.addEventListener('contextmenu', handler, { once: true });
            node.dispatchEvent(new MouseEvent('contextmenu', { bubbles: true, cancelable: true }));
            setTimeout(() => resolve(false), 200);
        }));
        check('native menu kept on input', prevented === false);
        check('no custom menu after input right click', await page.$('[role="menu"]') == null);
    }

    // No browser console/page errors during the whole run.
    await browser.close();
    console.log(results.join('\n'));
    process.exit(results.some((line) => line.startsWith('FAIL')) ? 1 : 0);
})().catch((error) => { console.error(error); process.exit(1); });

