+    if (siteSearch) {
+        siteSearch.addEventListener("submit", (event) => {
+            event.preventDefault();
+            const query = new FormData(event.currentTarget).get("q")?.trim?.();
+            if (query) {
+                location.hash = href("/search?q=" + encodeURIComponent(query));
