+
+export function renderGoods(path, query = new URLSearchParams()) {
+    if (path !== basePath && !path.startsWith(basePath + "/")) return null;
+    if (path === basePath) return shell(path, "세종 굿즈", "무대의 기억을 일상으로 가져오세요.", collection());
