+    }, { signal });
+
+    page.addEventListener("click", (event) => {
+        const remove = event.target.closest("[data-goods-remove]");
+        if (remove) {
+            const id = remove.dataset.goodsRemove;
+            const title = findGood(id)?.title;
+            if (!title) return;
+            const row = remove.closest("[data-goods-cart-row]");
