+    const panel = root.querySelector("#program-share-panel");
+    const input = root.querySelector("#program-share-url");
+    // [공유 패널의 열기·닫기 / Reversible share-panel presence]
+    // 논리 상태는 즉시 바꾸고 닫힘 중 재입력과 Escape의 초점 복귀를 보존합니다.
