+      end: "2026-10-31",
+      venue: "세종대극장",
+    },
+    {
+      id: "b",
+      title: "빛의 전시",
+      category: "전시",
+      start: "2026-11-01",
+      end: "2026-11-20",
+      venue: "미술관",
+    },
+  ];
+  assert.deepEqual(
+    filterPrograms(rows, {
+      category: "공연",
+      date: "2026-10-31",
+      search: "  음악회  ",
+    }).map((x) => x.id),
+    ["a"],
+  );
+  assert.equal(
+    filterPrograms(rows, { date: "2026-11-01", category: "공연" }).length,
+    0,
+  );
