// v5 source tree: rename all JS product files to TS and fix import specifiers.
import fs from "fs";
import path from "path";
import http from "http";

const V5 = "C:/Users/hai".replace("hai", "hi") + "/renewsejongpac-3/v5"; // path guard against typos
const root = "C:/Users/hi/renewsejongpac-3/v5";
const src = path.join(root, "src");

const rel = (dir) =>
    fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
        const child = path.join(dir, entry.name);
        if (entry.isDirectory()) return rel(child);
        return child.endsWith(".js") && child.endsWith(".js") ? [child] : [];
    });

const all = rel(src);
const twins = new Set([
    path.join(src, "lib/core.ts"),
    path.join(src, "data/catalog.ts"),
    path.join(src, "features/home-domain.ts"),
    path.join(src, "lib/supabase.ts"),
]);

let renamed = 0;
let deleted = 0;
for (const file of all) {
    if (twins.has(file.replace(/\.js$/, ".ts"))) {
        fs.rmSync(file);
        deleted += 1;
    } else {
        fs.renameSync(file, file.replace(/\.js$/, ".ts"));
        renamed += 1;
    }
}
console.log(`src files renamed: ${renamed}, duplicate js removed: ${deleted}`);

// Rewrite relative ".js" specifiers pointing at converted modules to ".ts" in all touched files.
const spec = /\.js(["'])/g;
function fixSpecifiers(file) {
    const content = fs.readFileSync(file, "utf8");
    const start = content.slice(0, 120);
    if (!start.includes(".js") && !/from\s+["'][^"']*\.js/.test(content) && !/import\(\s*["'][^"']*\.js/.test(content)) return false;
    // Only rewrite specifiers that reference files inside v5/src (converted tree) or types/sejong.
    let out = content.replace(/(["'])(\.{1,2}\/(?:\.{1,2}\/)*)((?:[\w\-./]+))\.js\1/g, (whole, quote, dots, stem) => {
        const target = require.resolve(path.posix ? "node:path" : "node:path");
        return `${quote}${dots}${stem}.ts${quote}`;
    });
    if (out !== content) {
        fs.writeFileSync(file, out, "utf8");
        return true;
    }
    return false;
}

const walkCode = (dir, exts) =>
    fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
        const child = path.join(dir, entry.name);
        if (entry.isDirectory() && entry.name !== "node_modules" && entry.name !== ".next" && entry.name !== "out" && entry.name !== "_next" && entry.name !== "skills" && entry.name !== "v2") {
            return walkCode(child, exts);
        }
        return exts.some((e) => child.endsWith(e)) ? [child] : [];
    });

const codeFiles = [
    ...walkCode(src, [".ts"]),
    ...walkCode(path.join(root, "app"), [".ts", ".tsx"]),
    ...walkCode(path.join(root, "components"), [".ts", ".tsx"]),
];

let specFixed = 0;
for (const file of codeFiles) {
    const counter = fs.readFileSync(file, "utf8");
    if (fixSpecifiers(file)) specFixed += 1;
}
console.log(`import specifiers rewritten in ${specFixed} files`);

// Alias imports to shared types module with explicit .ts extension (needed for node type-stripping runs).
const aliasFix = /(["'])((?:\.\.?\/)*types\/sejong)\1/g;
let aliasCount = 0;
for (const file of codeFiles) {
    const content = fs.readFileSync(file, "utf8");
    const out = content.replace(aliasFix, (whole, quote, alias) => `${alias}.ts${quote}`);
    if (out !== content) {
        fs.writeFileSync(file, out, "utf8");
        aliasCount += 1;
    }
}
console.log(`types alias extended in ${aliasCount} files`);

