const fs = require("fs");
const text = fs.readFileSync("C:/Users/hi/renewsejongpac-3/v5/src/data/catalog.ts", "utf8");
const section = text.slice(text.indexOf("const rows:"), text.indexOf("export const PROGRAMS"));
// Each program row starts with `` ["id",`` on its own line.
const rows = section.split(/(?=\[$)/).filter(Boolean);
const records = [];
const blocks = section.match(/\[\n\s*\n?\s*"[a-z0-9-]+"/g) || [];
// Simpler: split on top-level row boundaries by line stacks.
const lines = section.split("\n");
let current = null;
let depth = 0;
for (const line of lines) {
    if (line.trim() === "[") { current = []; depth = 1; continue; }
    if (current && depth) {
        let d = depth;
        // naive row end detection: closing "]," or "]" and next "["
        if (line.trim() === "],") { current.push(line); records.push(current.join("\n")); current = null; depth = 0; continue; }
        current.push(line);
    }
}
const parsed = [];
for (const row of records) {
    const id = (row.match(/"([a-z0-9-]+)"/) || [])[1];
    const priceLines = [];
    const inner = row.split("\n");
    inner.forEach((line, index) => {
        const t = line.trim();
        if (t.endsWith(",") && !t.startsWith('"') && !/^[\[.]/.test(t) && !t.startsWith("image") && !t.startsWith("description")) {
            if (/^[\d,]+$/.test(t.slice(0, -1)) || t === "0," || /^-/.test(t)) priceLines.push(index + ": " + t);
            else if (!t.startsWith("/") && !t.endsWith(")") && !/^" /.test(t)) priceLines.push(index + ": ? " + t);
        }
    });
    parsed.push({ id, hint: priceLines.join(" | ") });
}
fs.writeFileSync("C:/Users/hi/AppData/Local/Temp/opencode/rows-prices.txt", parsed.map(p => p.id + "  " + p.hint).join("\n"));

