const fs = require("fs");
const path = require("path");
const root = "C:/Users/hi/renewsejongpac-3/v5";
const files = [
    "components/ProgramCard.tsx",
    "app/programs/[id]/ProgramDetailClient.tsx",
    "app/programs/[id]/page.tsx",
    "app/programs/page.tsx",
    "app/page.tsx",
    "app/booking/[id]/page.tsx",
    "app/booking/[id]/BookingClient.tsx",
];
for (const rel of files) {
    const file = path.join(root, rel);
    const original = fs.readFileSync(file, "utf8");
    const next = original.replace(
        /^(import) \{ (Program[^}]*) \} from ("[^"]*sejong\.ts")/m,
        "import type { $2 } from $3"
    );
    if (next !== original) {
        fs.writeFileSync(file, next);
        console.log("fixed", rel);
    } else {
        console.log("no-match", rel);
    }
}

