                                         data-visit-kind={guide.kind}
                                         className={activeVisitId === guide.id ? "is-active" : ""}
                                     />
                                 ))}
                             </div>
                         </div>
                     </div>
                 </div>
             </section>
 
             {/* 6. 소식과 참여 (News & Participation) */}
