const path = require('path');
const { chromium } = require(path.resolve('C:/Users/hi/renewsejongpac-3/v5/node_modules/playwright'));

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

async function sampleDeltas(canvas, samples, interval, page) {
    const results = [];
    for (let index = 0; index < samples; index++) {
        const snapshot = await page.evaluate(target => {
            const context = target.getContext('2d', { willReadFrequently: true });
            const frame = context.getImageData(0, 0, target.width, target.height).data;
            return Array.from(frame).filter((_, i) => i % 4 === 3 ? true : false)[0] === undefined ? 0 : Array.from(frame).reduce((sum, value) => sum + value, 0);
        }, canvas);
        results.push(snapshot);
        await sleep(interval);
    }
    return results;
}

(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
    await page.goto('http://127.0.0.1:3000/v5/', { waitUntil: 'domcontentloaded' });
    await sleep(600);

    const info = await page.evaluate(() => {
        const canvases = Array.from(document.querySelectorAll('canvas[data-violet-fur]'));
        return canvases.map(canvas => ({
            kind: canvas.getAttribute('data-violet-fur'),
            width: canvas.width,
            height: canvas.height,
            cssWidth: canvas.clientWidth,
            cssHeight: canvas.clientHeight,
            visible: !!(canvas.offsetWidth || canvas.offsetHeight || canvas.getClientRects().length),
        }));
    });
    console.log('CANVAS INFO', JSON.stringify(info));

    async function layeredProbe(kind) {
        return page.evaluate(token => {
            const canvas = document.querySelector(`canvas[data-violet-fur="${token}"]`);
            if (!canvas) return null;
            const context = canvas.getContext('2d', { willReadFrequently: true });
            if (!context) return null;
            window.__furProbe = window.__furProbe || {};
            window.__furProbe[token] = { context, canvas, previous: null, deltas: [], maxDelta: 0, samples: 0 };
            return { width: canvas.width, height: canvas.height };
        }, kind);
    }

    // Probe helper: read the canvas back repeatedly, diff successive frames.
    async function measuring(token) {
        await layeredProbe(token);
        await page.evaluate(token => {
            const state = window.__furProbe[token];
            state.samples = 0;
            state.deltas = [];
            state.maxDelta = 0;
            state.previous = null;
        }, token);
        return true;
    }

    // Poll wrapper called from page context each frame is heavy; instead collect N reads here.
    const readFrame = (token) => page.evaluate(token => {
        const state = window.__furProbe[token];
        const { context, canvas } = state;
        const image = context.getImageData(0, 0, canvas.width, canvas.height);
        const buffer = image.data;
        if (state.previous) {
            let changed = 0;
            let maxDelta = 0;
            for (let index = 0; index < buffer.length; index += 4) {
                const delta = Math.abs(buffer[index] - state.previous[index]);
                if (delta > 12) changed++;
                if (delta > maxDelta) maxDelta = delta;
            }
            state.changed = changed;
            state.maxDelta = Math.max(state.maxDelta, maxDelta);
            state.samples++;
            state.deltas.push(changed);
        }
        state.previous = new Uint8ClampedArray(buffer);
        return { samples: state.samples, changed: state.changed, maxDelta: state.maxDelta };
    }, token);

    await measuring('resting');
    let resting = { samples: 0, changedMax: 0, maxDelta: 0 };
    for (let index = 0; index < 24; index++) {
        const read = await readFrame('resting');
        resting.samples = read.samples;
        resting.changedMax = Math.max(resting.changedMax, read.changed || 0);
        resting.maxDelta = Math.max(resting.maxDelta, read.maxDelta || 0);
        await sleep(90);
    }
    console.log('RESTING IDLE', JSON.stringify(resting));

    // Open the wheel by hovering, then spin it, and repeat the probe on the expanded canvas.
    await page.mouse.move(640, 760);
    await sleep(260);
    const openSeen = await page.evaluate(() => document.querySelector('[data-violet-menu]')?.getAttribute('data-state'));
    console.log('STATE', openSeen, 'clientHeight', await page.evaluate(() => window.innerHeight));
    const box = await page.evaluate(() => {
        const wheel = document.querySelector('[data-violet-wheel]');
        const rect = wheel.getBoundingClientRect();
        return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2, radius: rect.width / 2 };
    });
    await page.mouse.move(box.x + box.radius * .66, box.y + box.radius * .5);
    await page.mouse.down();
    await measuring('expanded');
    let spinning = { samples: 0, changedMax: 0, maxDelta: 0 };
    for (let angle = 0; angle < 22; angle++) {
        const theta = angle / 22 * Math.PI * 2;
        await page.mouse.move(box.x + Math.cos(theta) * box.radius * .72, box.y + Math.sin(theta) * box.radius * .72, { steps: 2 });
        const read = await readFrame('expanded');
        if (read) {
            spinning.samples = read.samples;
            spinning.changedMax = Math.max(spinning.changedMax, read.changed || 0);
            spinning.maxDelta = Math.max(spinning.maxDelta, read.maxDelta || 0);
        }
        await sleep(70);
    }
    await page.mouse.up();
    console.log('SPINNNG EXPANDED', JSON.stringify(spinning));
    await browser.close();
})();

