// Open the wheel by hovering the toggle, idle-probe the expanded fur, then spin it.
const toggle = await page.evaluate(() => {
    const target = document.querySelector('[data-violet-toggle]') || document.querySelector('button');
    const rect = target.getBoundingClientRect();
    return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
});
await page.mouse.move(toggle.x, toggle.y, { steps: 4 });
await sleep(500);
const openSeen = await page.evaluate(() => document.querySelector('[data-violet-menu]')?.getAttribute('data-state'));
console.log('STATE', openSeen);
await sleep(700);
const box = await page.evaluate(() => {
    const wheel = document.querySelector('[data-violet-wheel]');
    const rect = wheel.getBoundingClientRect();
    return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2, radius: rect.width / 2 };
});
await measuring('expanded');
let expandedIdle = { samples: 0, changedMax: 0, maxDelta: 0 };
for (let index = 0; index < 24; index++) {
    const read = await readFrame('expanded');
    expandedIdle.samples = read.samples;
    expandedIdle.changedMax = Math.max(expandedIdle.changedMax, read.changed || 0);
    expandedIdle.maxDelta = Math.max(expandedIdle.maxDelta, read.maxDelta || 0);
    await sleep(90);
}
console.log('EXPANDED IDLE', JSON.stringify(expandedIdle));
await page.mouse.move(box.x + box.radius * .66, box.y + box.radius * .5);

