const { chromium } = require('playwright');

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
    await page.goto('http://127.0.0.1:3000/v5/', { waitUntil: 'domcontentloaded' });
    await sleep(700);

    await page.evaluate(() => {
        const probes = {};
        window.__probe = token => {
            const canvas = document.querySelector(`canvas[data-violet-fur="${token}"]`);
            if (!canvas) return null;
            const context = canvas.getContext('2d', { willReadFrequently: true });
            if (!context) return null;
            let previous = null;
            return () => {
                const buffer = context.getImageData(0, 0, canvas.width, canvas.height).data;
                if (previous && previous.length === buffer.length) {
                    let moved = 0;
                    let energy = 0;
                    let maxDelta = 0;
                    for (let index = 0; index < buffer.length; index += 4) {
                        const delta = Math.abs(buffer[index] - previous[index]);
                        if (delta > 5) moved++;
                        energy += delta;
                        if (delta > maxDelta) maxDelta = delta;
                    }
                    previous = buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.length).slice();
                    return { moved, energy, maxDelta };
                }
                previous = buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.length).slice();
                return { moved: 0, energy: 0, maxDelta: 0, warmup: true };
            };
        };
    });

    // Freeze/unfreeze rAF for the motionless control.
    const toggleRaf = async freeze => page.evaluate(frozen => {
        if (frozen) {
            window.__rafBackup = window.requestAnimationFrame;
            window.requestAnimationFrame = () => 0;
        } else if (window.__rafBackup) {
            window.requestAnimationFrame = window.__rafBackup;
            window.__rafBackup = null;
        }
    }, freeze);

    async function run(kind, tokens) {
        const read = await page.evaluate(token => {
            window.__readers = window.__readers || {};
            if (!window.__readers[token]) window.__readers[token] = window.__probe(token);
            return { width: document.querySelector(`canvas[data-violet-fur="${token}"]`).width };
        }, kind);
        const samples = [];
        for (let index = 0; index < tokens; index++) {
            const data = await page.evaluate(token => window.__readers[token](), kind);
            samples.push(data);
            await sleep(85);
        }
        const movedMax = Math.max(...samples.map(data => data.moved || 0));
        const energyMax = Math.max(...samples.map(data => data.energy || 0));
        return `${kind}: movedMax=${movedMax} energyMax=${energyMax}`;
    }

    console.log('REST idle     ', await run('resting', 22));
    await toggleRaf(true);
    await sleep(120);
    console.log('REST frozenCTL', await run('resting', 6));
    await toggleRaf(false);
    await sleep(120);

    const toggleBox = await page.evaluate(() => {
        const target = document.querySelector('[data-violet-toggle]') || document.querySelector('button');
        const rect = target.getBoundingClientRect();
        return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
    });
    await page.mouse.move(toggleBox.x, toggleBox.y, { steps: 4 });
    await sleep(600);
    console.log('STATE', await page.evaluate(() => document.querySelector('[data-violet-menu]')?.getAttribute('data-state')));
    await sleep(600);

    console.log('OPEN idle     ', await run('expanded', 22));
    await toggleRaf(true);
    await sleep(120);
    console.log('OPEN frozenCTL', await run('expanded', 6));
    await toggleRaf(false);

    const box = await page.evaluate(() => {
        const wheel = document.querySelector('[data-violet-wheel]');
        const rect = wheel.getBoundingClientRect();
        return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2, radius: rect.width / 2 };
    });
    await page.mouse.move(box.x + box.radius * .7, box.y + box.radius * .45);
    await page.mouse.down();
    const spin = [];
    for (let angle = 0; angle < 22; angle++) {
        const theta = angle / 22 * Math.PI * 2;
        await page.mouse.move(box.x + Math.cos(theta + 2.2) * box.radius * .72, box.y + Math.sin(theta + 2.2) * box.radius * .72, { steps: 2 });
        spin.push(await page.evaluate(token => window.__readers[token](), 'expanded'));
        await sleep(60);
    }
    await page.mouse.up();
    console.log('SPIN          ', `expanded: movedMax=${Math.max(...spin.map(data => data.moved || 0))} energyMax=${Math.max(...spin.map(data => data.energy || 0))}`);

    await browser.close();
})();

