    const box = await page.evaluate(() => {
        const wheel = document.querySelector('[data-violet-wheel]');
        const rect = wheel.getBoundingClientRect();
        return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2, radius: rect.width / 2 };
    });
    // Pointer sweep near the rim (no press) drives the proximity push.
    await measuringSweep();
    for (let angle = 0; angle < 10; angle++) {
        const theta = angle / 10 * Math.PI * 2;
        await page.mouse.move(box.x + Math.cos(theta) * box.radius * .92, box.y + Math.sin(theta) * box.radius * .92, { steps: 3 });
        await sleep(55);
    }
    console.log('SWEEP         ', await collect('expanded'));
    // Grip edge (r~.92) so the press never lands on a menu link, then arc the drag.
    await page.mouse.move(box.x + box.radius * .92, box.y);
    await page.mouse.down();
    for (let angle = 0; angle < 22; angle++) {
        const theta = angle / 22 * Math.PI * 2;
        await page.mouse.move(box.x + Math.cos(theta) * box.radius * .92, box.y + Math.sin(theta) * box.radius * .92, { steps: 2 });
        await sleep(60);
    }
    await page.mouse.up();
    console.log('SPIN          ', await collect('expanded'));
    console.log('STATE-AFTER   ', await page.evaluate(() => document.querySelector('[data-violet-menu]')?.getAttribute('data-state')));

    async function measuringSweep() {
        await page.evaluate(() => { window.__readers = window.__readers || {}; window.__readers.expanded = window.__probe('expanded'); });
    }
    async function collect(token) {
        const samples = [];
        for (let index = 0; index < 12; index++) {
            samples.push(await page.evaluate(tok => window.__readers[tok](), token));
            await sleep(80);
        }
        return `${token}: movedMax=${Math.max(...samples.map(data => data.moved || 0))} energyMax=${Math.max(...samples.map(data => data.energy || 0))}`;
    }

    await browser.close();
})();

