const fs = require('fs');
const { chromium } = require('playwright');

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

(async () => {
    const browser = await chromium.launch({ headless: false });
    const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
    await page.goto('http://127.0.0.1:3000/v5/', { waitUntil: 'domcontentloaded' });
    await sleep(800);

    await page.evaluate(() => {
        window.__probe = token => {
            const canvas = document.querySelector(`canvas[data-violet-fur="${token}"]`);
            if (!canvas) return null;
            const context = canvas.getContext('2d', { willReadFrequently: true });
            if (!context) return null;
            let previous = null;
            return () => {
                const buffer = context.getImageData(0, 0, canvas.width, canvas.height).data;
                if (previous && previous.length === buffer.length) {
                    let moved = 0;
                    let energy = 0;
                    for (let index = 0; index < buffer.length; index += 4) {
                        const delta = Math.abs(buffer[index] - previous[index]);
                        if (delta > 5) moved++;
                        energy += delta;
                    }
                    previous = Buffer.from(buffer).toString('base64');
                    return { moved, energy };
                }
                previous = Buffer.from(buffer).toString('base64');
                return { moved: 0, energy: 0, warmup: true };
            };
        };
        window.__readers = window.__readers || {};
        window.__readers.resting = window.__probe('resting');
    });

    const samples = [];
    for (let index = 0; index < 20; index++) {
        samples.push(await page.evaluate(() => window.__readers.resting()));
        await sleep(90);
    }
    console.log('REST idle     ', `resting: movedMax=${Math.max(...samples.map(data => data.moved || 0))} energyMax=${Math.max(...samples.map(data => data.energy || 0))}`);

    const toggleBox = await page.evaluate(() => {
        const target = document.querySelector('[data-violet-toggle]') || document.querySelector('button');
        const rect = target.getBoundingClientRect();
        return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2, w: rect.width, h: rect.height };
    });
    for (let shot = 0; shot < 4; shot++) {
        await page.screenshot({
            path: `C:\\Users\\hi\\AppData\\Local\\Temp\\opencode\\orb-${shot}.png`,
            clip: { x: toggleBox.x - toggleBox.w, y: toggleBox.y - toggleBox.h * 2, width: toggleBox.w * 3, height: toggleBox.h * 4 },
        });
        await sleep(500);
    }

    await page.mouse.move(toggleBox.x, toggleBox.y, { steps: 4 });
    await sleep(700);
    console.log('STATE', await page.evaluate(() => document.querySelector('[data-violet-menu]')?.getAttribute('data-state')));
    await sleep(600);

    await page.evaluate(() => { window.__readers.expanded = window.__probe('expanded'); });
    const open = [];
    for (let index = 0; index < 20; index++) {
        open.push(await page.evaluate(() => window.__readers.expanded()));
        await sleep(90);
    }
    console.log('OPEN idle     ', `expanded: movedMax=${Math.max(...open.map(data => data.moved || 0))} energyMax=${Math.max(...open.map(data => data.energy || 0))}`);

    const box = await page.evaluate(() => {
        const wheel = document.querySelector('[data-violet-wheel]');
        const rect = wheel.getBoundingClientRect();
        return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2, radius: rect.width / 2 };
    });

    // Pointer sweep near the rim (no press) drives the proximity push.
    for (let angle = 0; angle < 10; angle++) {
        const theta = angle / 10 * Math.PI * 2;
        await page.mouse.move(box.x + Math.cos(theta) * box.radius * .92, box.y + Math.sin(theta) * box.radius * .92, { steps: 3 });
        await sleep(55);
    }
    const sweep = [];
    for (let index = 0; index < 12; index++) {
        sweep.push(await page.evaluate(() => window.__readers.expanded()));
